package com.loadoutstudio;
import com.google.gson.*;import java.util.*;import javax.swing.*;import net.runelite.api.gameval.ItemID;import net.runelite.http.api.RuneLiteAPI;import org.junit.Test;import static org.junit.Assert.*;
public class BankPauseAndCosmeticTest {
 private static JsonObject setup(){JsonObject p=SetupCodec.blank("Pause test");SetupCodec.setup(p).getAsJsonArray("inv").set(0,SetupCodec.item(ItemID.SHARK,1));SetupCodec.rebuildLayout(p);return p;}
 @Test public void normalBankPauseRetainsLoadoutUntilExplicitReturnOrReopen(){BankFilterTest.FakeBank bank=new BankFilterTest.FakeBank();bank.open=true;StudioBankFilter f=new StudioBankFilter(bank,"studio");f.select(setup());f.pause();assertNull(bank.active);assertTrue(f.apply().startsWith("Showing your Bank"));assertNull(bank.active);f.apply(true);assertEquals("studio",bank.active);f.pause();f.bankOpened();f.apply();assertEquals("studio",bank.active);}
 @Test public void backgroundDraftRefreshDoesNotCancelPauseAndClearDoesNotResume(){BankFilterTest.FakeBank bank=new BankFilterTest.FakeBank();bank.open=true;StudioBankFilter f=new StudioBankFilter(bank,"studio");f.select(setup());f.pause();f.select(setup());assertNull(bank.active);f.clear();f.bankOpened();assertEquals("Bank filter off.",f.apply());}
 @Test public void sixCosmeticArmourPairsFilterAndOfferTheObservedVariantWithoutChangingExports(){
  int[] variants={ItemID.TORVA_HELM_SANGUINE,ItemID.TORVA_CHEST_SANGUINE,ItemID.TORVA_LEGS_SANGUINE,ItemID.RADIANT_OATHPLATE_HELM,ItemID.RADIANT_OATHPLATE_CHEST,ItemID.RADIANT_OATHPLATE_LEGS};int[] slots={0,4,7,0,4,7};SetupCodec codec=new SetupCodec(RuneLiteAPI.GSON);
  for(int i=0;i<variants.length;i++){int variant=variants[i],base=EquipmentVariants.base(variant),slot=slots[i];JsonObject p=SetupCodec.blank("Armour");SetupCodec.setup(p).getAsJsonArray("eq").set(slot,SetupCodec.item(base,1));SetupCodec.rebuildLayout(p);BankFilterTest.FakeBank bank=new BankFilterTest.FakeBank();bank.open=true;StudioBankFilter f=new StudioBankFilter(bank,"studio");f.select(p);assertTrue(bank.matches.test(variant));assertEquals(base,f.layoutItemId(variant));Map<Integer,StudioPanel.ItemInfo> items=new HashMap<>();items.put(variant,OwnedGearTest.item(variant,"Cosmetic armour",slot));OwnedGear owned=new OwnedGear(Collections.singletonMap(variant,1),items,1,true);assertEquals(variant,owned.alternatives(p,n->null).get(0).choices.get(0).id);SetupCodec.setup(p).getAsJsonArray("eq").set(slot,SetupCodec.item(variant,1));SetupCodec.rebuildLayout(p);assertEquals(variant,SetupCodec.id(SetupCodec.setup(codec.importText(codec.inventory(p)).get(0)).getAsJsonArray("eq").get(slot)));}
 }
 @Test public void builderSectionCreationKeepsUnsavedNotesAndSelectsTheNewOrExistingSection()throws Exception{SwingUtilities.invokeAndWait(()->{PanelTest.FakeHost host=new PanelTest.FakeHost();StudioPanel p=new StudioPanel(host,RuneLiteAPI.GSON);p.newDraft(setup());((JTextArea)OwnedGearPanelTest.find(p,"loadoutNotes")).setText("Unsaved notes");p.createBuilderSection("Bossing");p.createBuilderSection(" bossing ");OwnedGearPanelTest.click(p,"Save");SetupLibrary l=SetupLibrary.read(host.saved,RuneLiteAPI.GSON);assertEquals(1,l.sections.size());assertEquals(l.sections.get(0).id,l.setups.get(0).section);assertEquals("Unsaved notes",SetupCodec.setup(l.setups.get(0).portable).get("notes").getAsString());p.dispose();});}
 @Test public void invalidBuilderSectionDoesNotWriteTheLibrary()throws Exception{SwingUtilities.invokeAndWait(()->{PanelTest.FakeHost host=new PanelTest.FakeHost();StudioPanel p=new StudioPanel(host,RuneLiteAPI.GSON);p.newDraft(setup());try{p.createBuilderSection(" ");fail();}catch(IllegalArgumentException expected){}assertNull(host.saved);p.dispose();});}
}
